#!/bin/sh
# LOCAL DEMO ONLY: entrypoint wrapper used by docker-compose.yaml.
#
# Loads the secrets generated by scripts/demo-secrets.sh into the environment
# and then runs the real command. In a deployment these variables come from
# the platform's secret manager and this script is not used.
set -eu
s=/run/demo-secrets
db="postgresql:5432/loandesk"

export DEMO_SECRETS=true
export ENCRYPTION_KEY_HEX="$(cat $s/encryption_key_hex)"
# After `demo-secrets rotate` the active key id and the previous key come from
# the volume too (scripts/demo-secrets.sh); before that, from the Compose file.
if [ -s $s/encryption_key_id ]; then
  export ENCRYPTION_KEY_ID="$(cat $s/encryption_key_id)"
fi
if [ -s $s/encryption_previous_keys_json ]; then
  export ENCRYPTION_PREVIOUS_KEYS_JSON="$(cat $s/encryption_previous_keys_json)"
elif [ -s $s/encryption_key_id ]; then
  unset ENCRYPTION_PREVIOUS_KEYS_JSON
fi
export S3_ACCESS_KEY_ID="$(cat $s/s3_access_key)"
export S3_SECRET_ACCESS_KEY="$(cat $s/s3_secret_key)"
export DATABASE_URL="postgresql://loandesk_app:$(cat $s/db_app_password)@$db"
export MIGRATION_DATABASE_URL="postgresql://loandesk_owner:$(cat $s/db_owner_password)@$db"
if [ "${USE_MIGRATION_ROLE:-false}" = "true" ]; then
  # Migration jobs connect as the schema owner; everything else as the restricted role.
  export DATABASE_URL="$MIGRATION_DATABASE_URL"
fi
if [ -n "${WORKER_HTTP_ADDR:-}" ]; then
  export WORKER_CONTROL_TOKEN="$(cat $s/worker_control_token)"
fi
# An empty endpoint means "no collector": logs still go to stdout as JSON.
[ -n "${OTEL_EXPORTER_OTLP_ENDPOINT:-}" ] || unset OTEL_EXPORTER_OTLP_ENDPOINT

exec "$@"
